function safeLink(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
const media=value=>/^\/media\/[a-f0-9]{32}\.jpg$/.test(value||'')||/^data:image\/(png|jpeg|webp);base64,/.test(value||'')?value:'';

function sampleVisual(p) {
 if(p.source!=='seed')return null;
 const id=p.id||'';const key=p.visual||(id.includes('design')?'architecture':id.includes('science')?'space':id.includes('flower')?'flower':id.includes('rocket')?'rocket':'mountain');
 return window.SynapseVisuals?.[key]||null;
}
function sampleAvatar(a){const key=({synapse:'mountain',lia:'architecture',caio:'space',nina:'flower',leo:'rocket',luna:'mountain'})[a.id];return a.seeded&&key?window.SynapseVisuals?.[key]?.src:'';}
function brandSymbol(){return '<svg class="synapse-symbol" viewBox="0 0 36 36" aria-hidden="true"><path d="M18 2c2.5 9.5 6.5 13.5 16 16-9.5 2.5-13.5 6.5-16 16C15.5 24.5 11.5 20.5 2 18 11.5 15.5 15.5 11.5 18 2Z" fill="currentColor"/><circle cx="29" cy="6" r="3" fill="currentColor"/></svg>';}

function avatar(a,size=''){
 a=a||{name:'Você',color:'violet'};const picture=media(a.avatar_path)||sampleAvatar(a);
 return `<span class="avatar ${esc(a.color||'violet')} ${size}">${picture?`<img src="${esc(picture)}" alt="${a.seeded?'Imagem editorial do perfil de exemplo':'Foto de '+esc(a.name)}">`:esc(a.name.split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase())}</span>`;
}
function ago(value){const d=Math.max(0,(Date.now()-new Date(value))/1000);return d<60?'agora':d<3600?`${Math.floor(d/60)} min`:d<86400?`${Math.floor(d/3600)} h`:new Date(value).toLocaleDateString('pt-BR',{day:'numeric',month:'short'});}
const host=value=>{try{return new URL(value).hostname.replace(/^www\./,'');}catch{return 'link';}};
const bodyText=value=>esc(value).replace(/(^|\s)(#[\p{L}\p{N}_]+)/gu,'$1<span class="hashtag">$2</span>');
